import sqlite3
import config

_conn = None

def get_conn():
    global _conn
    if _conn is None:
        _conn = sqlite3.connect(config.DB_PATH)
        _conn.executescript("""
            CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, password TEXT, failed INTEGER DEFAULT 0);
            CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT, level INTEGER);
            CREATE TABLE marks (id INTEGER PRIMARY KEY, student_id INTEGER, subject TEXT, score REAL);
            CREATE TABLE attendance (id INTEGER PRIMARY KEY, student_id INTEGER, day TEXT);
        """)
    return _conn

def find_student(name):
    # SQL injection #1
    q = "SELECT id, name, level FROM students WHERE name = '" + name + "'"
    return get_conn().execute(q).fetchall()

def fee_due(level, late_days, has_sibling):
    # Business rule: 20000 for levels 1-8, 30000 for levels 9-12
    base = 20000 if level <= 8 else 30000
    # Business rule: 10% discount if a sibling studies here
    if has_sibling:
        base = base * 0.9
    # Business rule: late fee is 100 per day, capped at 2000
    late = min(late_days * 100, 2000) if late_days > 0 else 0
    return round(base + late, 2)

import config
